-- MindCare Diary - Oracle AI Database 26ai schema
-- Generated from branch: feature/oracle-db
-- Repository: ericaokamura/mindcare-diary
-- Run this script while connected as schema owner MINDCARE.
--
-- IMPORTANT:
-- Usuario uses SINGLE_TABLE inheritance. Therefore Paciente and Profissional
-- subclass fields live in USUARIO, not in separate PACIENTE/PROFISSIONAL tables.
--
-- Identity columns use GENERATED BY DEFAULT so explicit IDs from migrated
-- PostgreSQL data can still be inserted.
--
-- Spring AI is configured with:
--   spring.ai.vectorstore.oracle.initialize-schema=true
-- so VECTOR_STORE is left to Spring AI to initialize.

CREATE TABLE USUARIO (
    ID                    NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    DTYPE                 VARCHAR2(31 CHAR) NOT NULL,
    NOME_USUARIO          VARCHAR2(255 CHAR),
    SENHA                 VARCHAR2(255 CHAR),
    NOME_COMPLETO         VARCHAR2(255 CHAR),
    DATA_NASCIMENTO       DATE,
    GENERO                VARCHAR2(255 CHAR),
    ATIVO                 NUMBER(1) DEFAULT 0 NOT NULL,
    DATA_HORA_ATIVACAO    TIMESTAMP(6),
    TOKEN                 VARCHAR2(255 CHAR),
    USER_ROLE             VARCHAR2(255 CHAR),
    BLOQUEADO             NUMBER(1) DEFAULT 0 NOT NULL,
    ENCERRADA_EM          TIMESTAMP(6),
    PROTOCOLO_ELIMINACAO  VARCHAR2(255 CHAR),

    ESTADO_PACIENTE       VARCHAR2(255 CHAR),

    TIPO_PROFISSIONAL     VARCHAR2(255 CHAR),
    REGISTRO_PROFISSIONAL VARCHAR2(255 CHAR),
    CLINICA_ID            NUMBER(19),

    CONSTRAINT PK_USUARIO PRIMARY KEY (ID),
    CONSTRAINT CK_USUARIO_ATIVO CHECK (ATIVO IN (0,1)),
    CONSTRAINT CK_USUARIO_BLOQUEADO CHECK (BLOQUEADO IN (0,1)),
    CONSTRAINT CK_USUARIO_GENERO CHECK (
        GENERO IS NULL OR GENERO IN ('FEMININO','MASCULINO')
    ),
    CONSTRAINT CK_USUARIO_ROLE CHECK (
        USER_ROLE IS NULL OR USER_ROLE IN ('PACIENTE','PROFISSIONAL','ADMIN')
    ),
    CONSTRAINT CK_USUARIO_ESTADO CHECK (
        ESTADO_PACIENTE IS NULL OR
        ESTADO_PACIENTE IN ('ESTAVEL','ATENCAO','MELHORANDO')
    ),
    CONSTRAINT CK_USUARIO_TIPO_PROF CHECK (
        TIPO_PROFISSIONAL IS NULL OR
        TIPO_PROFISSIONAL IN ('PSICOLOGO','PSIQUIATRA')
    )
);

