-- DROP TABLE MINDCARE.CLINICA;

CREATE TABLE CLINICA (
	TAXA_COMISSAO FLOAT,
	ADMIN_ID NUMBER(19,0),
	ID NUMBER(19,0) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
	CNPJ VARCHAR2(255),
	ENDERECO VARCHAR2(255),
	NOME VARCHAR2(255),
	PLANO_ASSINATURA VARCHAR2(255),
	CONSTRAINT SYS_C0010462 CHECK ("ID" IS NOT NULL),
	CONSTRAINT SYS_C0010463 CHECK (plano_assinatura in ('BASICO','PROFISSIONAL','CLINICA')),
	CONSTRAINT SYS_C0010464 PRIMARY KEY (ID)
);

ALTER TABLE CLINICA ADD CONSTRAINT "FK8906XXGJYMTTG10JDVCCC8SMK" FOREIGN KEY ("ADMIN_ID")
	  REFERENCES USUARIO ("ID") DISABLE;

ALTER TABLE USUARIO
ADD CONSTRAINT FK_USUARIO_CLINICA
FOREIGN KEY (CLINICA_ID) REFERENCES CLINICA(ID);

CREATE TABLE ACEITE_TERMOS (
    ID               NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    USUARIO_ID       NUMBER(19) NOT NULL,
    VERSAO           VARCHAR2(255 CHAR),
    HASH_DOCUMENTOS  VARCHAR2(255 CHAR),
    ACEITO_EM        TIMESTAMP(6) WITH TIME ZONE,

    CONSTRAINT PK_ACEITE_TERMOS PRIMARY KEY (ID),
    CONSTRAINT FK_ACEITE_USUARIO
        FOREIGN KEY (USUARIO_ID) REFERENCES USUARIO(ID)
);

CREATE TABLE CONSULTA (
    ID                  NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    NUMERO              VARCHAR2(255 CHAR),
    PROFISSIONAL_ID     NUMBER(19),
    PACIENTE_ID         NUMBER(19),
    CLINICA_ID          NUMBER(19),
    VALOR_CONSULTA      FLOAT,
    CONSULTA_MODALIDADE VARCHAR2(255 CHAR),
    DATA_HORA_CONSULTA  TIMESTAMP(6),
    ATENDIDA            NUMBER(1) DEFAULT 0 NOT NULL,
    CANCELADA           NUMBER(1) DEFAULT 0 NOT NULL,

    CONSTRAINT PK_CONSULTA PRIMARY KEY (ID),
    CONSTRAINT CK_CONSULTA_ATENDIDA CHECK (ATENDIDA IN (0,1)),
    CONSTRAINT CK_CONSULTA_CANCELADA CHECK (CANCELADA IN (0,1)),
    CONSTRAINT CK_CONSULTA_MODALIDADE CHECK (
        CONSULTA_MODALIDADE IS NULL OR
        CONSULTA_MODALIDADE IN ('PRESENCIAL','TELECONSULTA')
    ),
    CONSTRAINT FK_CONSULTA_PROF
        FOREIGN KEY (PROFISSIONAL_ID) REFERENCES USUARIO(ID),
    CONSTRAINT FK_CONSULTA_PAC
        FOREIGN KEY (PACIENTE_ID) REFERENCES USUARIO(ID),
    CONSTRAINT FK_CONSULTA_CLINICA
        FOREIGN KEY (CLINICA_ID) REFERENCES CLINICA(ID)
);

CREATE TABLE PACIENTE_PROFISSIONAL (
    PACIENTE_ID     NUMBER(19) NOT NULL,
    PROFISSIONAL_ID NUMBER(19) NOT NULL,

    CONSTRAINT PK_PACIENTE_PROFISSIONAL
        PRIMARY KEY (PACIENTE_ID, PROFISSIONAL_ID),
    CONSTRAINT FK_PP_PACIENTE
        FOREIGN KEY (PACIENTE_ID) REFERENCES USUARIO(ID),
    CONSTRAINT FK_PP_PROFISSIONAL
        FOREIGN KEY (PROFISSIONAL_ID) REFERENCES USUARIO(ID)
);

CREATE TABLE PRESCRIPTION_DOCUMENT (
    ID              NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    PRESCRIPTION_ID NUMBER(19),
    ARQUIVO_PDF     BLOB,
    NOME_ARQUIVO    VARCHAR2(255 CHAR),
    CONTENT_TYPE    VARCHAR2(255 CHAR),
    TAMANHO_BYTES   NUMBER(19),
    CRIADO_EM       TIMESTAMP(6),

    CONSTRAINT PK_PRESCRIPTION_DOCUMENT PRIMARY KEY (ID),
    CONSTRAINT UK_PRESCRIPTION_DOCUMENT_PRES UNIQUE (PRESCRIPTION_ID)
);

CREATE TABLE PRESCRIPTION (
    ID                       NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    NUMERO                   VARCHAR2(255 CHAR),
    ISSUE_DATE               DATE,
    EXPIRATION_DATE          DATE,
    DAYS_REMAINING           NUMBER(19),
    PACIENTE_ID              NUMBER(19),
    PROFISSIONAL_ID          NUMBER(19),
    CONTROLLED               NUMBER(1) DEFAULT 0 NOT NULL,
    VALID                    NUMBER(1) DEFAULT 0 NOT NULL,
    PRESCRIPTION_DOCUMENT_ID NUMBER(19),

    CONSTRAINT PK_PRESCRIPTION PRIMARY KEY (ID),
    CONSTRAINT CK_PRESCRIPTION_CONTROLLED CHECK (CONTROLLED IN (0,1)),
    CONSTRAINT CK_PRESCRIPTION_VALID CHECK (VALID IN (0,1)),
    CONSTRAINT UK_PRESCRIPTION_DOCUMENT UNIQUE (PRESCRIPTION_DOCUMENT_ID),
    CONSTRAINT FK_PRESCRIPTION_PAC
        FOREIGN KEY (PACIENTE_ID) REFERENCES USUARIO(ID),
    CONSTRAINT FK_PRESCRIPTION_PROF
        FOREIGN KEY (PROFISSIONAL_ID) REFERENCES USUARIO(ID),
    CONSTRAINT FK_PRESCRIPTION_DOC
        FOREIGN KEY (PRESCRIPTION_DOCUMENT_ID)
        REFERENCES PRESCRIPTION_DOCUMENT(ID)
);

ALTER TABLE PRESCRIPTION_DOCUMENT
ADD CONSTRAINT FK_PRES_DOC_PRESCRIPTION
FOREIGN KEY (PRESCRIPTION_ID) REFERENCES PRESCRIPTION(ID);

CREATE TABLE PRESCRIPTION_MEDICINES (
    PRESCRIPTION_ID NUMBER(19) NOT NULL,
    MEDICINES       VARCHAR2(255 CHAR),

    CONSTRAINT FK_PRES_MED_PRESCRIPTION
        FOREIGN KEY (PRESCRIPTION_ID) REFERENCES PRESCRIPTION(ID)
);

-- Profissional.abordagens does NOT specify @Enumerated.
-- Hibernate/JPA therefore uses ORDINAL by default.
CREATE TABLE PRESCRIPTION_ABORDAGENS (
    PROFISSIONAL_ID NUMBER(19) NOT NULL,
    ABORDAGENS      NUMBER(10),

    CONSTRAINT FK_PRES_ABORD_PROF
        FOREIGN KEY (PROFISSIONAL_ID) REFERENCES USUARIO(ID),
    CONSTRAINT CK_PRES_ABORDAGEM CHECK (
        ABORDAGENS IS NULL OR ABORDAGENS BETWEEN 0 AND 5
    )
);

-- Profissional.especialidades does NOT specify @Enumerated.
-- Hibernate/JPA therefore uses ORDINAL by default.
CREATE TABLE PRESCRIPTION_ESPECIALIDADES (
    PROFISSIONAL_ID NUMBER(19) NOT NULL,
    ESPECIALIDADES  NUMBER(10),

    CONSTRAINT FK_PRES_ESP_PROF
        FOREIGN KEY (PROFISSIONAL_ID) REFERENCES USUARIO(ID),
    CONSTRAINT CK_PRES_ESPECIALIDADE CHECK (
        ESPECIALIDADES IS NULL OR ESPECIALIDADES BETWEEN 0 AND 6
    )
);

CREATE TABLE REGISTRO_DIARIO (
    ID                    NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    PACIENTE_ID           NUMBER(19),
    NIVEL_HUMOR           VARCHAR2(255 CHAR),
    PONTOS_POSITIVOS      VARCHAR2(255 CHAR),
    DIFICULDADES_DESAFIOS VARCHAR2(255 CHAR),
    DATA_HORA_CRIACAO     TIMESTAMP(6),
    TEXTO_CONFIRMADO      VARCHAR2(4000 CHAR),
    ORIGEM                VARCHAR2(20 CHAR) DEFAULT 'TRADITIONAL' NOT NULL,
    ID_REQUISICAO         VARCHAR2(36 CHAR),

    CONSTRAINT PK_REGISTRO_DIARIO PRIMARY KEY (ID),
    CONSTRAINT CK_REGISTRO_NIVEL_HUMOR CHECK (
        NIVEL_HUMOR IS NULL OR
        NIVEL_HUMOR IN (
            'OTIMO','BOM','NEUTRO','MAL','PESSIMO','SEM_DEFINICAO'
        )
    ),
    CONSTRAINT CK_REGISTRO_ORIGEM CHECK (
        ORIGEM IN ('TRADITIONAL','CHAT')
    ),
    CONSTRAINT FK_REGISTRO_PACIENTE
        FOREIGN KEY (PACIENTE_ID) REFERENCES USUARIO(ID)
);

CREATE TABLE RELATORIO_SEMANAL (
    ID                NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    NUMERO            VARCHAR2(255 CHAR),
    PACIENTE_ID       NUMBER(19),
    FAIXA_DE_DATAS    VARCHAR2(255 CHAR),
    OBSERVACOES       VARCHAR2(255 CHAR),
    RECOMENDACOES     VARCHAR2(255 CHAR),
    RELATORIO_IA      CLOB,
    DATA_HORA_CRIACAO TIMESTAMP(6),
    TOTAL_POSITIVOS   NUMBER(10) DEFAULT 0 NOT NULL,
    TOTAL_NEGATIVOS   NUMBER(10) DEFAULT 0 NOT NULL,
    RESUMO            VARCHAR2(255 CHAR),

    CONSTRAINT PK_RELATORIO_SEMANAL PRIMARY KEY (ID),
    CONSTRAINT FK_RELATORIO_PACIENTE
        FOREIGN KEY (PACIENTE_ID) REFERENCES USUARIO(ID)
);

-- Hibernate implicit join table generated by:
-- @ManyToMany private List<RegistroDiario> registrosDiarios;
CREATE TABLE RELATORIO_SEMANAL_REGISTROS_DIARIOS (
    RELATORIO_SEMANAL_ID NUMBER(19) NOT NULL,
    REGISTROS_DIARIOS_ID NUMBER(19) NOT NULL,

    CONSTRAINT UK_RELATORIO_REGISTRO UNIQUE (REGISTROS_DIARIOS_ID),
    CONSTRAINT FK_RSRD_RELATORIO
        FOREIGN KEY (RELATORIO_SEMANAL_ID)
        REFERENCES RELATORIO_SEMANAL(ID),
    CONSTRAINT FK_RSRD_REGISTRO
        FOREIGN KEY (REGISTROS_DIARIOS_ID)
        REFERENCES REGISTRO_DIARIO(ID)
);

CREATE INDEX IX_USUARIO_CLINICA
    ON USUARIO(CLINICA_ID);

CREATE INDEX IX_CLINICA_ADMIN
    ON CLINICA(ADMIN_ID);

CREATE INDEX IX_ACEITE_USUARIO
    ON ACEITE_TERMOS(USUARIO_ID);

CREATE INDEX IX_CONSULTA_PROF
    ON CONSULTA(PROFISSIONAL_ID);

CREATE INDEX IX_CONSULTA_PAC
    ON CONSULTA(PACIENTE_ID);

CREATE INDEX IX_CONSULTA_CLINICA
    ON CONSULTA(CLINICA_ID);

CREATE INDEX IX_PRESCRIPTION_PAC
    ON PRESCRIPTION(PACIENTE_ID);

CREATE INDEX IX_PRESCRIPTION_PROF
    ON PRESCRIPTION(PROFISSIONAL_ID);

CREATE INDEX IX_REGISTRO_PAC
    ON REGISTRO_DIARIO(PACIENTE_ID);

CREATE INDEX IX_RELATORIO_PAC
    ON RELATORIO_SEMANAL(PACIENTE_ID);

COMMIT;


