-- registro_diario
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (7, TO_TIMESTAMP('2026-08-23 21:17:04.536437', 'YYYY-MM-DD HH24:MI:SS.FF'), 'Tive uma discussao com a minha mae.', 'BOM', 'Fui elogiada pelo meu chefe.', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (8, TO_TIMESTAMP('2026-08-26 01:58:41.109769', 'YYYY-MM-DD HH24:MI:SS.FF'), '', 'BOM', 'Hoje consegui terminar uma tarefa importante que estava adiando há alguns dias. Fiquei bastante satisfeita com o resultado e senti que consegui organizar melhor meu tempo.', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (9, TO_TIMESTAMP('2026-08-26 01:59:05.0305', 'YYYY-MM-DD HH24:MI:SS.FF'), 'Hoje tive um dia bastante cansativo. Algumas coisas não saíram como eu esperava e fiquei frustrada. No final do dia conversei com uma pessoa próxima e isso me ajudou a me sentir um pouco melhor.', 'MAL', '', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (10, TO_TIMESTAMP('2026-08-26 01:59:17.281365', 'YYYY-MM-DD HH24:MI:SS.FF'), '', 'BOM', 'Hoje encontrei alguns amigos e passamos algumas horas conversando. Foi muito bom rir e esquecer um pouco das preocupações do dia a dia.', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (11, TO_TIMESTAMP('2026-08-26 01:59:29.509091', 'YYYY-MM-DD HH24:MI:SS.FF'), 'Hoje precisei apresentar um trabalho. Antes da apresentação fiquei muito nervosa e imaginei que poderia esquecer o que precisava falar. Quando comecei, percebi que estava mais preparada do que imaginava e consegui terminar a apresentação.', 'NEUTRO', '', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (12, TO_TIMESTAMP('2026-08-26 01:59:45.601537', 'YYYY-MM-DD HH24:MI:SS.FF'), '', 'OTIMO', 'Hoje foi um dia mais tranquilo. Consegui fazer minhas atividades sem muita pressão e reservei um tempo para assistir a uma série e descansar.', 28, NULL, 'TRADITIONAL', NULL);
INSERT INTO registro_diario (id, data_hora_criacao, dificuldades_desafios, nivel_humor, pontos_positivos, paciente_id, id_requisicao, origem, texto_confirmado) VALUES (13, TO_TIMESTAMP('2026-08-26 01:59:58.476241', 'YYYY-MM-DD HH24:MI:SS.FF'), 'Hoje tive uma discussão com uma pessoa próxima. Na hora fiquei com muita raiva e preferi me afastar para não falar coisas das quais pudesse me arrepender. Depois de algum tempo consegui conversar com mais calma.', 'PESSIMO', '', 28, NULL, 'TRADITIONAL', NULL);

-- relatorio_semanal
INSERT INTO relatorio_semanal (id, data_hora_criacao, faixa_de_datas, observacoes, recomendacoes, relatorio_ia, paciente_id, total_negativos, total_positivos, resumo, numero) VALUES (68, TO_TIMESTAMP('2026-08-26 02:04:47.699878', 'YYYY-MM-DD HH24:MI:SS.FF'), '2026-08-19^2026-08-26', '', '', '1. Resumo geral da semana: A semana do paciente Helena Barbosa foi marcada por altos e baixos. Em alguns dias, ela se sentiu satisfeita e tranquila, enquanto em outros, se sentiu frustrada e com raiva.\n\n2. Humor predominante e sua evolução ao longo dos dias: O humor da paciente flutuou ao longo da semana, variando entre "ótimo", "bom", "mal" e "péssimo". Suas emoções parecem estar diretamente ligadas às suas experiências diárias.\n\n3. Principais emoções identificadas: As principais emoções expressas pela paciente foram satisfação, frustração, raiva e calma.\n\n4. Possíveis gatilhos emocionais ou situações recorrentes que impactaram o bem-estar: As dificuldades da paciente parecem estar ligadas a situações de estresse, expectativas não atendidas e conflitos interpessoais.\n\n5. Estratégias de enfrentamento ou recursos positivos mencionados pelo paciente: Helena mencionou a organização do tempo e a realização de tarefas como estratégias positivas. Ela também relatou que conversar com pessoas próximas e reservar tempo para atividades de lazer, como assistir séries, lhe ajudou a se sentir melhor.\n\n6. Sinais de melhora, estabilidade ou agravamento emocional: A paciente mostrou capacidade de enfrentamento, como afastar-se para evitar confrontos e buscar apoio em pessoas próximas. No entanto, a flutuação do seu humor sugere instabilidade emocional.\n\n7. Temas recorrentes observados nos relatos: As expectativas não atendidas e os conflitos interpessoais são temas recorrentes nos relatos da paciente. \n\n8. Recomendações e pontos de atenção para o profissional responsável: Recomenda-se que o profissional explore mais sobre os gatilhos emocionais da paciente e trabalhe na construção de estratégias de enfrentamento. A instabilidade emocional observada deve ser acompanhada de perto.\n\nNota: Este relatório se baseia em apenas quatro registros disponíveis e não em sete, como solicitado na pergunta. Portanto, pode não representar completamente a situação emocional da paciente durante a semana.', 28, 3, 4, NULL, '187654');

