-- =========================================================
-- ADVANCE IDENTITY GENERATORS
-- =========================================================
ALTER TABLE aceite_termos MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE clinica MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE consulta MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE prescription MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE prescription_document MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE registro_diario MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE relatorio_semanal MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE usuario MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

-- Re-enable and validate all foreign keys.
BEGIN
  FOR c IN (
    SELECT table_name, constraint_name
    FROM user_constraints
    WHERE constraint_type = 'R'
  ) LOOP
    BEGIN
      EXECUTE IMMEDIATE 'ALTER TABLE "' || c.table_name ||
                        '" ENABLE VALIDATE CONSTRAINT "' || c.constraint_name || '"';
    EXCEPTION
      WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Could not enable ' || c.table_name || '.' ||
                             c.constraint_name || ': ' || SQLERRM);
        RAISE;
    END;
  END LOOP;
END;

COMMIT;

